import java.io.BufferedInputStream
import java.io.BufferedOutputStream
import java.io.PrintWriter

class Interval(var l: Int, var r: Int)

private val inputStream = BufferedInputStream(System.`in`, 1024 * 10)
private val writer = PrintWriter(BufferedOutputStream(System.out, 1024 * 10))

fun main(args: Array<String>) {
    solve(args)
    writer.flush()
}

fun solve(args: Array<String>) {
    val n = nextInt()
    val k = nextInt()

    val l = IntArray(k)
    val r = IntArray(k)
    for (i in 0 until k) {
        l[i] = nextInt()
        r[i] = nextInt()
    }

    val size = 2 * k + 1
    val dp = Array(size) { mutableListOf<Interval>() }
    dp[0].add(Interval(0, 0))

    var prev = 0
    for (i in 0 until k) {
        val next = Array(size) { mutableListOf<Interval>() }

        var delta = l[i] - prev
        for (index in 0 until size) {
            if (index % 2 == 0) {
                for (interval in dp[index]) {
                    interval.l += delta
                    interval.r += delta
                }
            }
        }
        delta = r[i] - l[i]
        for (ii in 0 until size) {
            if (ii % 2 == 0) {
                for (interval in dp[ii]) {
                    next[ii].add(Interval(interval.l + delta, interval.r + delta))
                    next[ii + 1].add(Interval(interval.l, interval.r + delta))
                    next[ii + 2].add(Interval(interval.l, interval.r + delta))
                }
            } else {
                for (interval in dp[ii]) {
                    next[ii].add(Interval(interval.l, interval.r))
                    next[ii + 1].add(Interval(interval.l, interval.r + delta))
                    next[ii + 2].add(Interval(interval.l, interval.r + delta))
                }
            }
        }

        prev = r[i]
        for (index in 0 until size) {
            dp[index].clear()

            var pr: Interval? = null
            for (interval in next[index].sortedBy { it.l }) {
                if (interval.l > n)
                    break
                if (pr != null && pr!!.r >= interval.l) {
                    pr!!.r = maxOf(pr!!.r, interval.r)
                } else {
                    if (pr != null && !find(dp, pr!!, index))
                        dp[index].add(pr!!)
                    pr = interval
                }
            }
            if (pr != null && !find(dp, pr!!, index))
                dp[index].add(pr!!)
        }
    }

    run {
        val delta = 2 * n - prev
        for (index in 0 until size) {
            if (index % 2 == 0) {
                for (interval in dp[index]) {
                    interval.l += delta
                    interval.r += delta
                }
            }
        }
    }

    for (i in 0 until size) {
        for (interval in dp[i]) {
            if (interval.l <= n && interval.r >= n) {
                writer.println("Full")
                writer.println(i)
                return
            }
        }
    }

    writer.println("Hungry")
}

private fun find(dp: Array<MutableList<Interval>>, value: Interval, index: Int): Boolean {
    for (i in index - 2 downTo 0) {
        var ind = binarySearch(dp[i], value)
        if (ind < 0) {
            val insertionPoint = -ind - 1
            ind = insertionPoint - 1
            if (ind > 0 && dp[i][ind].r >= value.r) {
                return true
            }
        } else {
            if (dp[i][ind].r >= value.r)
                return true
        }
    }
    return false
}

private fun binarySearch(list: List<Interval>, value: Interval): Int {
    var lo = 0
    var hi = list.size - 1
    while (lo <= hi) {
        val mid = (lo + hi) ushr 1
        val cmp = list[mid].l.compareTo(value.l)
        if (cmp == 0) return mid
        if (cmp < 0) lo = mid + 1 else hi = mid - 1
    }
    return -(lo + 1)
}

private fun nextInt(): Int {
    var c: Int
    var res = 0
    do {
        c = inputStream.read()
        if (c == -1) return res
    } while (c < '0'.code || c > '9'.code)
    res = c - '0'.code
    while (true) {
        c = inputStream.read()
        if (c < '0'.code || c > '9'.code) return res
        res *= 10
        res += c - '0'.code
    }
}
